import{_ as o,l as n,o as a,c as l,v as t,p as s,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"日志结构文件系统 LFS","description":"","frontmatter":{"title":"日志结构文件系统 LFS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/log-structured-fs.md","filePath":"cs/log-structured-fs.md","lastUpdated":1789023840000}'),m={name:"cs/log-structured-fs.md"};function u(h,e,S,E,f,_){const r=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="日志结构文件系统-lfs" tabindex="-1">日志结构文件系统 LFS <a class="header-anchor" href="#日志结构文件系统-lfs" aria-label="Permalink to &quot;日志结构文件系统 LFS&quot;">​</a></h1><div class="epigraph"><p>把整盘当成一条无限追加的日志：新数据与新 inode 都写在日志头，旧版本靠垃圾回收收回。</p><footer>—— 据 Rosenblum and Ousterhout, The Design and Implementation of a Log-Structured File System, ACM TOCS 1992</footer></div><p><a href="/cs/ext4-extents">上一课</a>把块图收成 extent，但更新仍是<strong>原地</strong>：改一个 inode 就回去写那几个元数据块。<a href="/cs/ext4-journal">日志</a> 只是把即将发生的原地写先抄一份。缺口是更彻底的一步：主文件系统自己就是日志。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1990 年代内存已经能缓存读，磁盘的随机写仍贵。若所有脏数据与 inode 都排成顺序写，吞吐接近顺序带宽。代价：文件位置不再稳定，必须有 imap（inode map）指出「当前 inode 在日志的哪一段」；旧段变成垃圾，需要 cleaner。缺口不是再讲 JBD2 的 commit 块，而是 LFS 的段、检查点与 imap。</p><p>本课不把 F2FS 的多头日志提前写完。</p><p><span class="marginnote">检查点把 imap 的根与日志头钉到固定位置，崩溃后从检查点滚日志。cleaner 读段用法统计，把还活着的 inode/数据搬到日志头，释放整段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：缓冲若干脏页与脏 inode，凑成一段（segment）顺序下盘，更新内存 imap，定期把 imap 页也追加进日志并写检查点。读：imap → inode → 块地址（地址现在是日志里的偏移）→ <a href="/cs/page-cache">页缓存</a>。与 ext4 对照：没有「inode 表槽位永远在块组里」；槽位是逻辑号，物理位置随版本走。</p>',9)),(a(),s(c,null,{default:i(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIRTY%5B%22%E8%84%8F%E9%A1%B5%E4%B8%8E%20inode%22%5D%20--%3E%20SEG%5B%22%E8%BF%BD%E5%8A%A0%E4%B8%80%E6%AE%B5%E6%97%A5%E5%BF%97%22%5D%0A%20%20SEG%20--%3E%20IMAP%5B%22%E6%9B%B4%E6%96%B0%20imap%22%5D%0A%20%20IMAP%20--%3E%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20OLD%5B%22%E6%97%A7%E6%AE%B5%22%5D%20--%3E%20CL%5B%22cleaner%20%E6%90%AC%E6%B4%BB%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LFS 把随机元数据写变成顺序带宽，崩溃恢复顺着日志重放即可，不必 <a href="/cs/fsck">fsck</a> 扫整盘——后课会对照。闪存友好是后话：当时动机是 HDD 臂。cleaner 在空闲低时与前台写争带宽，这是 LFS 的经典税。不要把 LFS 写成数据库 WAL：WAL 旁边还有堆文件；LFS 的堆就是日志本身。</p><p>VFS 仍看见稳定的 inode 号；imap 才是「号 → 日志位置」的翻译，类似 FAT 表，但指向的是版本化对象而不是簇链。</p><p>实现上：imap 本身也必须可检查点，否则崩溃后找不到任何 inode。Sprite LFS 的 cleaner 在空闲低于阈值时与前台写争带宽，这是追加布局的周期性税，不是偶发 bug。 读法上只引用<a href="/cs/ext4-extents">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>日志结构文件系统 LFS</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 NAND 的擦除单元与 FTL。不保证 cleaner 在满盘时仍有好的吞吐——那是实现与负载的边界。下一课看闪存上长出来的后裔：F2FS 如何用多条日志头与节点地址表落地同一直觉。</p><p>版本字段会变，课序钉的是机制对象「日志结构文件系统 LFS」，不是某一主线内核的结构体名。 后课默认：文件系统可以是追加日志加 imap。面向闪存的节点表与热冷分离，下一课 F2FS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LFS 追加段；imap 翻译 inode 号；cleaner 回收旧段。</li><li>检查点给出崩溃后的根。</li><li>闪存上的多头日志是 F2FS 的缺口。</li><li>出处：Rosenblum and Ousterhout, TOCS 1992；<em>OSTEP</em> 对 LFS 的章节。</li></ul>',11))])}const B=o(m,[["render",u]]);export{A as __pageData,B as default};
